css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;
  --src-nata: #ec4899;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-pills {
  width: min(560px, 100%);
  display: grid; gap: 8px;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
}

.bs-pill {
  display: flex; align-items: center; gap: 8px;
  padding: 12px; border-radius: 10px;
  font-family: var(--fonte); font-size: 13px; font-weight: 500;
  color: var(--text-muted); background: var(--bg-card);
  /* Sempre 1.5px: trocar a espessura junto com a seleção empurraria as
     pílulas vizinhas meio pixel a cada clique. */
  border: 1.5px solid var(--border);
  transition: color 0.15s ease, background-color 0.15s ease, border-color 0.15s ease;
}

.bs-pill-ponto { width: 8px; height: 8px; flex-shrink: 0; border-radius: 999px; background: var(--cor); }

.bs-pill.bs-sel {
  font-weight: 600; color: var(--text);
  border-color: color-mix(in srgb, var(--cor) 40%, transparent);
  background: color-mix(in srgb, var(--cor) 15%, transparent);
}
